import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

// In Next.js 16 the `middleware` file convention was renamed to `proxy`.
// This runs on the server before every request completes, which makes it
// the right place to log incoming requests.
export function proxy(request: NextRequest) {
  console.log(`[${new Date().toISOString()}] ${request.method} ${request.nextUrl.pathname}${request.nextUrl.search}`)

  return NextResponse.next()
}

// Without a `matcher`, the proxy runs on every request (including static
// assets), which is what we want for request logging.
export const config = {
  matcher: [
    // Match all paths, including those starting with _next.
    '/((?!_next/static|_next/image|favicon.ico).*)',
  ],
}

